package android.graphics;public class Bitmap{public static class Config{public static final Config ARGB_8888=new Config();}public int w,h;public int[] pixels;public boolean recycled;public Bitmap(int[] p,int w,int h){pixels=p;this.w=w;this.h=h;}public static Bitmap createBitmap(int[] p,int w,int h,Config c){return new Bitmap(p.clone(),w,h);}public int getWidth(){return w;}public int getHeight(){return h;}public void getPixels(int[] out,int offset,int stride,int x,int y,int width,int height){System.arraycopy(pixels,0,out,0,pixels.length);}public void recycle(){recycled=true;}}